export function text(value: unknown): string {
  if (value == null) return "";
  if (value instanceof Date) return value.toISOString();
  return String(value);
}

export function yesNo(value: unknown): string {
  return value == null ? "" : value ? "Yes" : "No";
}

/** Currencies whose minor unit is not a hundredth: the fraction digits an amount is shown with (2 otherwise) */
const MINOR_UNITS: Record<string, number> = { BHD: 3, BIF: 0, CLP: 0, DJF: 0, GNF: 0, IQD: 3, ISK: 0, JOD: 3, JPY: 0, KMF: 0, KRW: 0, KWD: 3, LYD: 3, OMR: 3, PYG: 0, RWF: 0, TND: 3, UGX: 0, VND: 0, VUV: 0, XAF: 0, XOF: 0, XPF: 0 };

/**
 * An amount with its currency, from the decimal string as the API sent it: digits are grouped and trailing zeros
 * past the currency's minor unit dropped. The string is never read as a number, and nothing is rounded.
 */
export function formatMoney(value: unknown, currency: unknown): string {
  if (value == null || value === "") return "";
  const raw = text(value);
  const code = text(currency);
  const [whole, fraction = ""] = raw.replace("-", "").split(".");
  const kept = fraction.replace(/0+$/, "").padEnd(MINOR_UNITS[code] ?? 2, "0");
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return `${raw.startsWith("-") ? "-" : ""}${grouped}${kept ? "." + kept : ""}${code ? " " + code : ""}`;
}

export function formatDateTime(value: unknown): string {
  if (value == null || value === "") return "";
  const date = new Date(value as string);
  return Number.isNaN(date.getTime()) ? text(value) : date.toLocaleString();
}

export function formatList(value: unknown): string {
  return Array.isArray(value) ? value.map(text).join(", ") : text(value);
}

export function formatJson(value: unknown): string {
  return value == null ? "" : JSON.stringify(value, null, 2);
}

/** A datetime as the value of an <input type="datetime-local"> */
export function toDateTimeInput(value: unknown): string {
  if (!value) return "";
  const date = new Date(value as string);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

export function splitList(value: string): string[] {
  return value
    .split(",")
    .map(s => s.trim())
    .filter(Boolean);
}

/** A value after it has stopped changing for `delay` milliseconds */
export function useDebounced<T>(value: T, delay = 300): T {
  const [settled, setSettled] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setSettled(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return settled;
}

